/* Checked personal calibration for duration, recovery and self-rated workload. */
(function(root){
'use strict';
const VERSION=1,LAMBDA=5,MIN_TRAIN=6,MIN_CHECKS=4;
function number(v,min=0,max=Infinity){if(!(typeof v==='number'||typeof v==='string'&&v.trim()!==''))return null;const n=Number(v);return Number.isFinite(n)&&n>=min&&n<=max?n:null;}
function config(mode,dimension){const income=mode==='income',effort=dimension==='effort';return {mode,dimension,min:effort&&!income?1:0,max:effort?(income?10:5):income?168:dimension==='recovery'?1440:100000,unit:effort?(income?'points /10':'points /5'):income?'hours/week':'minutes',log:!effort,gain:effort?.05:income?.1:1};}
function forecasts(item){if(item.preparationStudy)return null;if(item.resourceForecasts?.version===VERSION)return ['decision','income'].includes(item.resourceForecasts.mode)?item.resourceForecasts:null;const income=item.decisionType==='income';if(income){const x=item.incomeTradeoff?.x;if(!x)return null;return {version:VERSION,mode:'income',a:{duration:x.hoursB,recovery:x.recoveryB,effort:x.effortB},b:{duration:x.hoursA,recovery:x.recoveryA,effort:x.effortA}};}return {version:VERSION,mode:'decision',a:{duration:item.minutes,recovery:item.recovery===''?0:item.recovery,effort:item.energy},b:{duration:item.altMinutes,recovery:item.altRecovery===''?0:item.altRecovery,effort:item.altEffort}};}
function observations(items,asOf=Date.now()){const out=[],seen=new Set();for(const item of items){if(!item||typeof item.id!=='string'||seen.has(item.id)||item.simulated)continue;seen.add(item.id);const saved=forecasts(item),outcome=item.resourceOutcomes,decisionAt=Date.parse(item.date);if(!saved||!['do','alt'].includes(outcome?.choice)||!Number.isFinite(decisionAt))continue;if(['do','alt'].includes(item.outcomeChoice)&&item.outcomeChoice!==outcome.choice)continue;const context=['everyday','purchase','relationship','income'].includes(item.decisionType)?item.decisionType:'everyday',side=outcome.choice==='do'?'a':'b';for(const dimension of ['duration','recovery','effort']){const cfg=config(saved.mode,dimension),entry=outcome[dimension],forecast=number(saved[side]?.[dimension],cfg.min,cfg.max),actual=number(entry?.value,cfg.min,cfg.max),observedAt=Date.parse(entry?.recordedAt);if(forecast===null||actual===null||entry?.confirmed!==true||!Number.isFinite(observedAt)||observedAt<=decisionAt||observedAt>asOf)continue;out.push({id:item.id+':'+dimension,context,mode:saved.mode,dimension,decisionAt,observedAt,forecast,actual});}}return out;}
const transform=(f,c)=>c.log?Math.log1p(f):f;
const feature=(f,c)=>c.log?Math.log1p(f)/5:(f-(c.min+c.max)/2)/((c.max-c.min)/2);
function fit(rows,c){if(!rows.length)return null;let a=rows.length+LAMBDA,b=0,d=LAMBDA,u=0,v=0;for(const r of rows){const z=feature(r.forecast,c),error=transform(r.actual,c)-transform(r.forecast,c);b+=z;d+=z*z;u+=error;v+=z*error;}const determinant=a*d-b*b;return [(u*d-v*b)/determinant,(v*a-u*b)/determinant];}
function estimate(beta,forecast,c){const raw=transform(forecast,c)+beta[0]+beta[1]*feature(forecast,c),value=c.log?Math.expm1(raw):raw;return Math.max(c.min,Math.min(c.max,value));}
function supported(min,max,f,c){return c.log?Math.log1p(f)>=Math.log1p(min)-Math.log(2)&&Math.log1p(f)<=Math.log1p(max)+Math.log(2):f>=min-1&&f<=max+1;}
function train(input,c,asOf=Date.now()){const rows=input.filter(r=>r.mode===c.mode&&r.dimension===c.dimension&&number(r.forecast,c.min,c.max)!==null&&number(r.actual,c.min,c.max)!==null&&Number.isFinite(r.decisionAt)&&Number.isFinite(r.observedAt)&&r.observedAt>r.decisionAt&&r.observedAt<=asOf).map(r=>({...r,forecast:Number(r.forecast),actual:Number(r.actual)})).sort((a,b)=>a.observedAt-b.observedAt).slice(-200);let error=0,originalError=0,checked=0;const checks=[];for(const row of rows){const past=rows.filter(r=>r.id!==row.id&&r.observedAt<row.decisionAt);if(past.length<MIN_TRAIN||!supported(Math.min(...past.map(r=>r.forecast)),Math.max(...past.map(r=>r.forecast)),row.forecast,c))continue;const predicted=estimate(fit(past,c),row.forecast,c);error+=Math.abs(predicted-row.actual);originalError+=Math.abs(row.forecast-row.actual);checked++;checks.push({id:row.id,trainingIds:past.map(r=>r.id),predicted});}const mae=checked?error/checked:null,originalMae=checked?originalError/checked:null,ready=rows.length>=10&&checked>=MIN_CHECKS&&mae+c.gain<originalMae;return {version:VERSION,config:c,n:rows.length,checked,mae,originalMae,ready,beta:fit(rows,c),minForecast:rows.length?Math.min(...rows.map(r=>r.forecast)):null,maxForecast:rows.length?Math.max(...rows.map(r=>r.forecast)):null,checks,reason:rows.length<10?'Need 10 comparable resource outcomes.':checked<4?'Need four chronological checks with six prior outcomes each.':!ready?'No sufficient improvement over your original resource estimates.':'Correction improved resource estimates in chronological checks.'};}
function predict(model,forecast){const c=model.config,value=number(forecast,c.min,c.max);if(value===null)return {value:null,applied:false,reason:'Original estimate missing.'};if(!model.ready)return {value,applied:false,reason:model.reason};if(!supported(model.minForecast,model.maxForecast,value,c))return {value,applied:false,reason:'Outside the range supported by your history.'};return {value:estimate(model.beta,value,c),applied:true,reason:'Checked resource correction applied.'};}
function guardWeekly(learned,original,changes){if(learned.mode!=='income')return;for(const side of ['a','b'])if(learned[side].duration+learned[side].recovery>168){for(const d of ['duration','recovery']){learned[side][d]=original[side][d];for(const change of changes)if(change.side===side&&change.dimension===d){change.value=change.original;change.applied=false;change.reason='Combined weekly time would exceed 168 hours; using original estimates.';}}}}
function apply(raw,models,enabled=true){const learned=JSON.parse(JSON.stringify(raw)),changes=[];for(const side of ['a','b'])for(const dimension of ['duration','recovery','effort']){const m=models[dimension],original=number(raw[side]?.[dimension],m.config.min,m.config.max);if(original===null)continue;const p=enabled?predict(m,original):{value:original,applied:false,reason:'Resource learning is switched off.'};learned[side][dimension]=p.value;changes.push({side,dimension,original,value:p.value,applied:p.applied,reason:p.reason,unit:m.config.unit,n:m.n,checked:m.checked,mae:m.mae,originalMae:m.originalMae,coefficients:m.beta});}guardWeekly(learned,raw,changes);return {learned,changes,applied:changes.some(c=>c.applied)};}
const api={VERSION,LAMBDA,number,config,forecasts,observations,fit,estimate,train,predict,apply,guardWeekly};if(typeof module==='object'&&module.exports)module.exports=api;root.ResourceCalibration=api;
})(typeof globalThis!=='undefined'?globalThis:this);
